public without sharing class OpportunityPipelineHandler {
    private static Boolean isUpdatingAccounts = false;

    public static void handleTrigger() {
        if (isUpdatingAccounts) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isInsert || Trigger.isUndelete) {
            for (Opportunity opp : Trigger.new) {
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Opportunity opp : Trigger.new) {
                Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountIds.add(opp.AccountId);
                }
                if (oldOpp.AccountId != null && !oldOpp.IsClosed) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : Trigger.old) {
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        isUpdatingAccounts = true;
        try {
            Map<Id, Decimal> amountMap = new Map<Id, Decimal>();
            Map<Id, Integer> countMap = new Map<Id, Integer>();

            for (AggregateResult ar : [
                SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
                FROM Opportunity
                WHERE AccountId IN :accountIds AND IsClosed = false
                GROUP BY AccountId
            ]) {
                Id accId = (Id)ar.get('AccountId');
                Decimal totalAmount = (Decimal)ar.get('totalAmount');
                Integer oppCount = (Integer)ar.get('oppCount');
                amountMap.put(accId, totalAmount != null ? totalAmount : 0);
                countMap.put(accId, oppCount != null ? oppCount : 0);
            }

            List<Account> accounts = [
                SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
                FROM Account
                WHERE Id IN :accountIds
            ];

            List<Account> accountsToUpdate = new List<Account>();
            for (Account acc : accounts) {
                Decimal newAmount = amountMap.containsKey(acc.Id) ? amountMap.get(acc.Id) : 0;
                Integer newCount = countMap.containsKey(acc.Id) ? countMap.get(acc.Id) : 0;

                if (acc.FB_Open_Pipeline__c != newAmount || acc.FB_Open_Opportunities__c != newCount) {
                    acc.FB_Open_Pipeline__c = newAmount;
                    acc.FB_Open_Opportunities__c = newCount;
                    accountsToUpdate.add(acc);
                }
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
        } finally {
            isUpdatingAccounts = false;
        }
    }
}
