/**
 * Pushes every newly created Account to the ERP as a customer.
 *
 * The ERP callout cannot be executed directly inside an after insert trigger
 * ("uncommitted work pending"), so AccountTrigger hands the new accounts to
 * this class, which immediately enqueues Queueable jobs. Each Queueable sends
 * exactly one ERP request per account (a JSON array containing a single
 * customer), so the ERP team can trace every account on its own.
 *
 * A single Apex transaction may make at most 100 HTTP callouts, so the new
 * accounts are split into chunks of at most 100 accounts and one Queueable is
 * enqueued per chunk directly from the trigger. A marketplace batch of 200
 * accounts therefore results in two Queueables (2 x 100 requests).
 * (@future is not an option: only 50 future calls are allowed per
 * transaction, which is not enough for batches of up to 200 accounts.)
 */
public with sharing class ErpCustomerSync {

    /** Maximum number of HTTP callouts allowed per Apex transaction. */
    private static final Integer MAX_ACCOUNTS_PER_JOB = 100;

    /**
     * Entry point called by AccountTrigger (after insert).
     * Enqueues one Queueable per chunk of up to 100 accounts.
     */
    public static void syncNewAccounts(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Account> chunk = new List<Account>();
        for (Account acc : newAccounts) {
            chunk.add(acc);
            if (chunk.size() == MAX_ACCOUNTS_PER_JOB) {
                System.enqueueJob(new ErpCustomerSyncQueueable(chunk));
                chunk = new List<Account>();
            }
        }
        if (!chunk.isEmpty()) {
            System.enqueueJob(new ErpCustomerSyncQueueable(chunk));
        }
    }

    /**
     * Sends one ERP request per account. Never enqueues follow-up jobs (no
     * chaining): every job is enqueued up front by syncNewAccounts, so each
     * job runs in its own transaction with a full set of governor limits.
     */
    public class ErpCustomerSyncQueueable implements Queueable {

        private List<Account> accounts;

        public ErpCustomerSyncQueueable(List<Account> accounts) {
            this.accounts = accounts;
        }

        public void execute(QueueableContext context) {
            for (Account acc : accounts) {
                sendCustomerToErp(acc);
            }
        }
    }

    /**
     * POSTs a single customer to the ERP as a one-element JSON array:
     * [{"salesforceId":"001...","name":"Acme GmbH","country":"Germany"}]
     * The ERP answers 202 Accepted; error handling and retries are out of
     * scope for this ticket.
     */
    private static void sendCustomerToErp(Account acc) {
        CustomerPayload customer = new CustomerPayload(
            acc.Id,
            acc.Name,
            String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry
        );

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(new List<CustomerPayload>{ customer }));

        Http http = new Http();
        http.send(req);
    }

    /** JSON payload for a single ERP customer. */
    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(String salesforceId, String name, String country) {
            this.salesforceId = salesforceId;
            this.name = name;
            this.country = country;
        }
    }
}
