```apex
public with sharing class DealEventPublisher {
    private static final Integer MAX_EVENTS_PER_PUBLISH = 150;

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        Integer remainingDml = Limits.getLimitDMLStatements() - Limits.getDMLStatements();

        // Preferred path: publish one event per opportunity when the current
        // transaction still has enough DML budget for one publish per opportunity.
        if (opportunities.size() <= remainingDml) {
            for (Opportunity opportunity : opportunities) {
                Deal_Stage_Change__e event = new Deal_Stage_Change__e(
                    Opportunity_Id__c = opportunity.Id,
                    Stage__c = opportunity.StageName,
                    Amount__c = opportunity.Amount
                );

                results.add(EventBus.publish(event));
            }

            return results;
        }

        // Large-batch path: one publish per opportunity would exceed the DML limit.
        // Publish in chunks; EventBus.publish(List<SObject>) still returns one
        // SaveResult per event, in the same order as the events in the list.
        List<SObject> events = new List<SObject>(opportunities.size());

        for (Opportunity opportunity : opportunities) {
            events.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = opportunity.Id,
                Stage__c = opportunity.StageName,
                Amount__c = opportunity.Amount
            ));
        }

        for (Integer start = 0; start < events.size(); start += MAX_EVENTS_PER_PUBLISH) {
            Integer endIndex = Math.min(start + MAX_EVENTS_PER_PUBLISH, events.size());
            List<SObject> batch = new List<SObject>();

            for (Integer i = start; i < endIndex; i++) {
                batch.add(events[i]);
            }

            results.addAll(EventBus.publish(batch));
        }

        return results;
    }
}
