    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Index the contacts once by normalized email, keeping the first
        // contact (in contacts order) for each email.
        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact contact : contacts) {
                if (contact != null && String.isNotBlank(contact.Email)) {
                    String emailKey = contact.Email.trim().toLowerCase();
                    if (!firstContactIdByEmail.containsKey(emailKey)) {
                        firstContactIdByEmail.put(emailKey, contact.Id);
                    }
