            }
        }

        // One result per lead, in the same order as the leads list.
        List<Id> matches = new List<Id>();
        if (leads != null) {
            for (Lead lead : leads) {
                Id contactId = null;
                if (lead != null && String.isNotBlank(lead.Email)) {
                    contactId = firstContactIdByEmail.get(lead.Email.trim().toLowerCase());
