/**
 * RenewalReminderService sends renewal reminder emails to opportunity owners.
 *
 * GOVERNOR LIMIT NOTE:
 * Salesforce enforces a hard limit of 10 emails per synchronous Apex transaction.
 * The original requirement to call Messaging.sendEmail() once per opportunity inside
 * a loop for up to 200 opportunities will throw a System.LimitException
 * ("Too many Email Invocations: 11") after the 10th email.
 *
 * To handle up to 200 opportunities safely, this implementation:
 *   1. Processes up to 10 opportunities synchronously using the bulk API
 *      Messaging.sendEmail(List<SingleEmailMessage>), which sends up to 10 emails
 *      in a single invocation while respecting the per-transaction governor limit.
 *   2. Enqueues a Queueable chain (via a private static inner class) to process
 *      any remaining opportunities in subsequent transactions, each handling up to
 *      10 emails. This keeps the entire run bulk-safe and avoids the governor limit.
 *
 * Emails to internal users via setTargetObjectId do not consume the org's daily
 * external email allocation, but still count against the 10-per-transaction limit.
 */
public with sharing class RenewalReminderService {

    // Salesforce governor limit: maximum 10 emails per synchronous transaction
    private static final Integer MAX_EMAILS_PER_TRANSACTION = 10;

    /**
     * Sends renewal reminder emails to the owners of the given opportunities.
     * Processes up to 10 opportunities in the current transaction; any remainder
     * is enqueued for asynchronous processing via a Queueable chain.
     *
     * @param opportunityIds List of Opportunity Ids (up to 200)
     * @return Number of emails successfully sent in this transaction (0-10)
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Split IDs: current batch (max 10) and remaining for async processing
        List<Id> currentBatchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Id oppId : opportunityIds) {
            if (currentBatchIds.size() < MAX_EMAILS_PER_TRANSACTION) {
                currentBatchIds.add(oppId);
            } else {
                remainingIds.add(oppId);
            }
        }

        // Bulk SOQL: query only the opportunities in the current batch
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId, CloseDate
            FROM Opportunity
            WHERE Id IN :currentBatchIds
        ];

        // Build email messages for the current batch
        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            emails.add(buildReminderEmail(opp));
        }

        Integer successCount = 0;

        // Send emails in bulk using a single invocation (up to 10 emails)
        // This respects the 10-email governor limit while maintaining bulk safety.
        // If one email fails, the others in the batch are still attempted because
        // Messaging.sendEmail returns a result per email.
        if (!emails.isEmpty()) {
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails);

            for (Messaging.SendEmailResult result : results) {
                if (result.isSuccess()) {
                    successCount++;
                } else {
                    // Log the specific error but continue; other emails in the batch still go out
                    System.debug(LoggingLevel.WARN,
                        'Failed to send renewal reminder email: ' + result.getErrors());
                }
            }
        }

        // If there are more opportunities than can be processed in this transaction,
        // enqueue a Queueable to process the remainder in a new transaction.
        // This creates a chain of Queueables (max depth 50; we need ~19 for 200 records).
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new RenewalReminderQueueable(remainingIds));
        }

        return successCount;
    }

    /**
     * Builds a SingleEmailMessage for the opportunity owner.
     * Emails to internal users via setTargetObjectId do not consume the org's
     * daily external email allocation, but still count against the 10-per-transaction limit.
     */
    private static Messaging.SingleEmailMessage buildReminderEmail(Opportunity opp) {
        Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();

        // Target the internal user (owner) by Id
        email.setTargetObjectId(opp.OwnerId);
        email.setSaveAsActivity(false);

        email.setSubject('Renewal due: ' + opp.Name);

        // Plain-text body mentioning the close date
        email.setPlainTextBody(
            'Hello,\n\n' +
            'This is a reminder that the renewal for the following opportunity is due:\n\n' +
            'Opportunity: ' + opp.Name + '\n' +
            'Close Date: ' + opp.CloseDate + '\n\n' +
            'Please review the opportunity and take appropriate action.\n\n' +
            'Thank you.'
        );

        return email;
    }

    /**
     * Private static inner class to process remaining opportunities in subsequent
     * transactions. Each execution processes up to 10 opportunities and enqueues
     * another instance if more remain, forming a chain until all opportunities are
     * processed. This pattern is necessary because synchronous Apex cannot send
     * more than 10 emails per transaction.
     */
    private static class RenewalReminderQueueable implements Queueable {

        private List<Id> opportunityIds;

        public RenewalReminderQueueable(List<Id> opportunityIds) {
            this.opportunityIds = opportunityIds;
        }

        public void execute(QueueableContext context) {
            // Delegate back to the service to process the next batch of up to 10
            RenewalReminderService.sendReminders(opportunityIds);
        }
    }
}
