public inherited sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId != null && employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        Map<Id, Set<Id>> primaryOrgsByContact = new Map<Id, Set<Id>>();
        for (npe5__Affiliation__c aff : [
            SELECT npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Primary__c = true
        ]) {
            if (!primaryOrgsByContact.containsKey(aff.npe5__Contact__c)) {
                primaryOrgsByContact.put(aff.npe5__Contact__c, new Set<Id>());
            }
            primaryOrgsByContact.get(aff.npe5__Contact__c).add(aff.npe5__Organization__c);
        }

        List<npe5__Affiliation__c> newAffiliations = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);

            Set<Id> existingPrimaryOrgs = primaryOrgsByContact.get(contactId);
            if (existingPrimaryOrgs != null && existingPrimaryOrgs.contains(orgId)) {
                continue;
            }

            npe5__Affiliation__c newAff = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = orgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = Date.today()
            );
            newAffiliations.add(newAff);

            Contact con = new Contact(
                Id = contactId,
                npsp__Primary_Affiliation__c = orgId
            );
            contactsToUpdate.add(con);
        }

        if (!newAffiliations.isEmpty()) {
            insert newAffiliations;
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
