public with sharing class HouseholdService {

    private static Id householdRecordTypeId;

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty');
        }

        // Query the Household Account record type by DeveloperName (no hard-coded Ids)
        if (householdRecordTypeId == null) {
            RecordType rt = [
                SELECT Id
                FROM RecordType
                WHERE DeveloperName = 'HH_Account'
                AND SobjectType = 'Account'
                LIMIT 1
            ];
            householdRecordTypeId = rt.Id;
        }

        Savepoint sp = Database.setSavepoint();

        try {
            // Create the household account without setting the Name;
            // NPSP will automatically name it based on the contacts.
            Account household = new Account(
                RecordTypeId = householdRecordTypeId
            );
            insert household;

            // Assign all contacts to this single household
            for (Contact member : members) {
                member.AccountId = household.Id;
            }
            insert members;

            // Set the first contact as the primary contact
            household.npe01__One2OneContact__c = members[0].Id;
            update household;

            return household.Id;

        } catch (Exception e) {
            // Roll back to ensure no empty/extra household is left behind
            Database.rollback(sp);
            throw e;
        }
    }
}
