public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }
            if (request.opportunityId != null) {
                opportunityIds.add(request.opportunityId);
            }
            if (request.contactId != null) {
                contactIds.add(request.contactId);
            }
        }

        if (opportunityIds.isEmpty() || contactIds.isEmpty()) {
            return;
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        // Validate the entire call before any DML.
        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }

            Opportunity opportunity = opportunitiesById.get(request.opportunityId);
            if (opportunity == null || opportunity.Amount == null) {
                throw new SoftCreditException(
                    'Opportunity not found or has no amount: ' + request.opportunityId
                );
            }
            if (request.contactId == null) {
                throw new SoftCreditException('Contact Id is required.');
            }
            if (request.contactId == opportunity.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The opportunity primary contact cannot receive a partial soft credit.'
                );
            }
            if (
                request.amount == null ||
                request.amount <= 0 ||
                request.amount > opportunity.Amount
            ) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be positive and no greater than the opportunity amount.'
                );
            }
        }

        Map<String, List<OpportunityContactRole>> contactRolesByPair = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String key = pairKey(contactRole.OpportunityId, contactRole.ContactId);
            if (!contactRolesByPair.containsKey(key)) {
                contactRolesByPair.put(key, new List<OpportunityContactRole>());
            }
            contactRolesByPair.get(key).add(contactRole);
        }

        Map<String, List<npsp__Partial_Soft_Credit__c>> softCreditsByPair = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT
                Id,
                npsp__Opportunity__c,
                npsp__Contact__c,
                npsp__Amount__c,
                npsp__Role_Name__c,
                npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = pairKey(softCredit.npsp__Opportunity__c, softCredit.npsp__Contact__c);
            if (!softCreditsByPair.containsKey(key)) {
                softCreditsByPair.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            softCreditsByPair.get(key).add(softCredit);
        }

        List<OpportunityContactRole> contactRoleUpserts = new List<OpportunityContactRole>();
        List<OpportunityContactRole> contactRoleDeletes = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> targetContactRoleByPair = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }

            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existingRoles = contactRolesByPair.get(key);
            OpportunityContactRole targetRole;

            if (existingRoles == null || existingRoles.isEmpty()) {
                targetRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role,
                    IsPrimary = false
                );
                contactRoleUpserts.add(targetRole);
            } else {
                targetRole = existingRoles[0];

                // Guarantee exactly one contact role remains for this opportunity/contact pair.
                for (Integer i = 1; i < existingRoles.size(); i++) {
                    contactRoleDeletes.add(existingRoles[i]);
                }

                if (targetRole.Role != request.role) {
                    targetRole.Role = request.role;
                    contactRoleUpserts.add(targetRole);
                }
            }

            targetContactRoleByPair.put(key, targetRole);
        }

        if (!contactRoleDeletes.isEmpty()) {
            delete contactRoleDeletes;
        }
        if (!contactRoleUpserts.isEmpty()) {
            upsert contactRoleUpserts;
        }

        List<npsp__Partial_Soft_Credit__c> softCreditUpserts = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }

            String key = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = targetContactRoleByPair.get(key);
            List<npsp__Partial_Soft_Credit__c> existingSoftCredits = softCreditsByPair.get(key);
            npsp__Partial_Soft_Credit__c softCredit;

            if (existingSoftCredits != null && !existingSoftCredits.isEmpty()) {
                softCredit = existingSoftCredits[0];
                softCredit.npsp__Amount__c = request.amount;
                softCredit.npsp__Role_Name__c = request.role;
            } else {
                softCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId,
                    npsp__Amount__c = request.amount,
                    npsp__Role_Name__c = request.role
                );
            }

            softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRole.Id);
            softCreditUpserts.add(softCredit);
        }

        if (!softCreditUpserts.isEmpty()) {
            upsert softCreditUpserts;
        }
    }
}
