/**
 * Links parent Contacts to their children in NPSP by creating the
 * child -> parent "Parent" Relationship. NPSP's reciprocal trigger
 * automatically creates the matching parent -> child record (Son /
 * Daughter / Child based on the child's gender, per the Relationship
 * Lookup and the default "List Setting" reciprocal method).
 *
 * Bulk-safe and idempotent: uses a single SOQL query and a single DML
 * statement, and skips any pair that already has a Relationship in
 * either direction so the import can be re-run safely.
 */
public with sharing class FamilyService {

    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Gather every Contact involved in at least one valid pair.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: every Relationship whose two ends are both in
        // this batch. Used to skip pairs already linked in either direction.
        Set<String> linkedPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               AND npe4__RelatedContact__c IN :contactIds
        ]) {
            linkedPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            linkedPairs.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // Single DML statement: insert one child -> parent Relationship per
        // new pair. NPSP creates the reciprocal parent -> child record.
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String forwardKey = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);

            // Skip if any Relationship already links these two Contacts in
            // either direction, or if this pair was already queued above.
            if (linkedPairs.contains(forwardKey) || linkedPairs.contains(reverseKey)) {
                continue;
            }

            linkedPairs.add(forwardKey);
            linkedPairs.add(reverseKey);

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c = childId;
            rel.npe4__RelatedContact__c = parentId;
            rel.npe4__Type__c = PARENT_TYPE;
            rel.npe4__Status__c = CURRENT_STATUS;
            relationshipsToInsert.add(rel);
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    /** Directional key for an unordered pair of Contact Ids. */
    private static String pairKey(Id firstId, Id secondId) {
        return String.valueOf(firstId) + '|' + String.valueOf(secondId);
    }
}
