/**
 * TDTM trigger handler for the Opportunity object (NPSP Table-Driven Trigger Management).
 *
 * Registration (done by the admin, NOT in code): create an NPSP Trigger Handler record under
 * NPSP Settings > Trigger Configuration with:
 *   Class          = OPP_MajorGiftFollowUp_TDTM
 *   Object         = Opportunity
 *   Trigger Action = AfterInsert;AfterUpdate
 *   Load Order     = 5
 *   Asynchronous   = false (unchecked)
 *
 * No Apex trigger is created for this logic. NPSP's TDTM dispatcher only invokes this class
 * while the Trigger Handler record above is Active, so deactivating that record stops the logic.
 *
 * Behavior: when an Opportunity is inserted as Closed Won with Amount >= 5000, or is updated
 * so that it becomes Closed Won with Amount >= 5000 when it was not already both of those,
 * one follow-up Task is created per qualifying Opportunity:
 *   Subject      = 'Major gift thank-you call'
 *   Priority     = 'High'
 *   Status       = 'Not Started'
 *   WhatId       = the Opportunity
 *   WhoId        = the Opportunity's npsp__Primary_Contact__c (may be null)
 *   OwnerId      = the Opportunity's OwnerId
 *   ActivityDate = the Opportunity's CloseDate + 3 days
 *
 * Editing a gift that already qualified does NOT create another Task.
 *
 * Bulk safety: this handler issues 0 SOQL queries and returns its Tasks to the TDTM dispatcher
 * in one DmlWrapper, resulting in one insert DML statement for the whole batch.
 */
global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    /** Minimum Amount for a Closed Won gift to be treated as a major gift. */
    private static final Decimal MAJOR_GIFT_MIN_AMOUNT = 5000;

    /** Number of days after CloseDate that the follow-up Task is due. */
    private static final Integer FOLLOW_UP_TASK_DUE_IN_DAYS = 3;

    /**
     * Entry point called by NPSP's TDTM dispatcher for the Opportunity object.
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist,
            npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {

        // This handler is registered for AfterInsert and AfterUpdate only; guard anyway so the
        // logic can never fire for an unexpected action.
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
                && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return null;
        }

        // Index the pre-update versions of the Opportunities so we can tell whether a gift
        // already qualified before this transaction (in which case no new Task is created).
        // Built without SOQL: everything needed is already on the records TDTM passes in.
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            for (SObject oldRecord : oldlist) {
                Opportunity oldOpp = (Opportunity) oldRecord;
                oldOppsById.put(oldOpp.Id, oldOpp);
            }
        }

        // Collect the follow-up Tasks for all qualifying Opportunities in this batch.
        List<SObject> followUpTasks = new List<SObject>();

        for (SObject newRecord : newlist) {
            Opportunity opp = (Opportunity) newRecord;

            // Must be Closed Won with Amount >= 5000 now.
            if (!isClosedWonMajorGift(opp)) {
                continue;
            }

            // On update, skip gifts that were already Closed Won with Amount >= 5000 before
            // this transaction (e.g. an edit to an existing major gift), so we never create
            // a duplicate follow-up Task.
            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                if (oldOpp != null && isClosedWonMajorGift(oldOpp)) {
                    continue;
                }
            }

            followUpTasks.add(createFollowUpTask(opp));
        }

        if (followUpTasks.isEmpty()) {
            return null;
        }

        // Hand the Tasks to NPSP's TDTM dispatcher, which inserts them in one DML statement.
        // DmlWrapper(inserts, updates, deletes)
        return new npsp.TDTM_Runnable.DmlWrapper(followUpTasks, null, null);
    }

    /**
     * Returns true when the Opportunity is Closed Won with Amount >= 5000.
     * Uses IsClosed/IsWon rather than a literal StageName so the logic also works if the
     * org has renamed or added closed-won stages.
     */
    private static Boolean isClosedWonMajorGift(Opportunity opp) {
        return opp.IsClosed
                && opp.IsWon
                && opp.Amount != null
                && opp.Amount >= MAJOR_GIFT_MIN_AMOUNT;
    }

    /**
     * Builds the follow-up Task for a qualifying Opportunity.
     */
    private static Task createFollowUpTask(Opportunity opp) {
        Task followUp = new Task();
        followUp.Subject = 'Major gift thank-you call';
        followUp.Priority = 'High';
        followUp.Status = 'Not Started';
        followUp.WhatId = opp.Id;
        followUp.WhoId = opp.npsp__Primary_Contact__c; // may be null
        followUp.OwnerId = opp.OwnerId;
        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_TASK_DUE_IN_DAYS);
        }
        return followUp;
    }
}
