public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id userId = UserInfo.getUserId();
        final Integer CHUNK_SIZE = 1000;
        List<Id> ids = new List<Id>(recordIds);

        for (Integer i = 0; i < ids.size(); i += CHUNK_SIZE) {
            Integer endIndex = Math.min(i + CHUNK_SIZE, ids.size());
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < endIndex; j++) {
                chunk.add(ids[j]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE RecordId IN :chunk
                  AND UserId = :userId
                  AND HasEditAccess = true
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
